[{"order":1,"type":"heading","text":"Font Optimization and Script Loading Strategies in Next.js"},{"order":2,"type":"paragraph","text":"Web performance is heavily influenced by how external assets like fonts and scripts are loaded. Next.js provides built-in solutions, 'next/font' and 'next/script', designed to optimize these assets automatically. By self-hosting fonts and offering granular control over script execution, Next.js helps developers achieve excellent Core Web Vitals scores, particularly for Cumulative Layout Shift (CLS) and Largest Contentful Paint (LCP)."},{"order":3,"type":"subheading","text":"Optimizing Fonts with next/font"},{"order":4,"type":"paragraph","text":"The 'next/font' package automatically optimizes your fonts (including custom fonts) and removes external network requests for improved privacy and performance. It downloads Google Fonts at build time and hosts them alongside your static assets. This means no browser requests are sent to Google by the end-user."},{"order":5,"type":"code","text":"import { Inter, Roboto_Mono } from 'next/font/google';

const inter = Inter({
  subsets: ['latin'],
  display: 'swap',
  variable: '--font-inter',
});

export default function RootLayout({ children }) {
  return (
    <html lang="en" className={inter.variable}>
      <body className={inter.className}>{children}</body>
    </html>
  );
}"},{"order":6,"type":"bullet_point","text":"Zero Layout Shift: Next.js uses size-adjust properties to match fallback system fonts with the loaded web font, preventing layout jumps."},{"order":7,"type":"bullet_point","text":"Automatic Self-Hosting: Fonts are bundled with deployment assets, eliminating third-party tracking and reducing DNS lookup times."},{"order":8,"type":"subheading","text":"Using Local Fonts"},{"order":9,"type":"paragraph","text":"For custom or premium fonts not available on Google Fonts, 'next/font/local' allows you to specify local font files. Next.js will still optimize them and handle fallback sizing automatically."},{"order":10,"type":"code","text":"import localFont from 'next/font/local';

const myCustomFont = localFont({
  src: './fonts/MyFont-Regular.woff2',
  display: 'swap',
  variable: '--font-custom',
});

export default function App() {
  return (
    <main className={myCustomFont.className}>
      <h1>Welcome to Next.js with Local Fonts</h1>
    </main>
  );
}"},{"order":11,"type":"subheading","text":"Script Loading Strategies with next/script"},{"order":12,"type":"paragraph","text":"Loading third-party scripts (like analytics, ads, or chat widgets) can severely degrade page load performance. The 'next/script' component extends the standard HTML <script> tag, allowing you to define exactly when and how external scripts should load using the 'strategy' property."},{"order":13,"type":"code","text":"import Script from 'next/script';

export default function ContactPage() {
  return (
    <>
      <h1>Contact Us</h1>
      <Script
        src="https://example.com/analytics.js"
        strategy="afterInteractive"
        onLoad={() => console.log('Analytics script loaded successfully')}
      />
    </>
  );
}"},{"order":14,"type":"bullet_point","text":"beforeInteractive: Loads the script before any Next.js code and before page hydration occurs. Use this only for critical scripts like bot detection or consent management."},{"order":15,"type":"bullet_point","text":"afterInteractive: (Default) Loads the script immediately after the page becomes interactive. Ideal for tag managers and analytics that need to run early but shouldn't block initial rendering."},{"order":16,"type":"bullet_point","text":"lazyOnload: Loads the script lazily during browser idle time. Perfect for non-critical scripts like chat widgets, support tools, or social media embeds."},{"order":17,"type":"bullet_point","text":"worker: (Experimental) Offloads the script execution to a web worker using Partytown, freeing up the main thread for maximum UI responsiveness."},{"order":18,"type":"subheading","text":"Best Practices for Asset Optimization"},{"order":19,"type":"bullet_point","text":"Always use 'display: swap' in your font configurations to ensure text remains visible while the custom font is downloading."},{"order":20,"type":"bullet_point","text":"Prefer 'next/font' over standard CSS '@import' or '<link>' tags to benefit from automatic preloading and layout shift mitigation."},{"order":21,"type":"bullet_point","text":"Audit third-party scripts regularly and assign the least intrusive strategy possible (e.g., 'lazyOnload' instead of 'afterInteractive' for non-essential widgets)."}]
